  {
    "question": "Which statement correctly defines a function f : X → Y?",
    "options": {
      "A": "Each element of X is associated with at most one element of Y.",
      "B": "Each element of Y is associated with exactly one element of X.",
      "C": "Each element of X is associated with at least one element of Y.",
      "D": "Each element of X is associated with exactly one element of Y."
    },
    "correct_answer": "D",
    "explanation": "By definition, a function assigns exactly one image in Y to every element of the domain X.",
    "difficulty": "Medium"
  },
  {
    "question": "Let A = {1,2,3} and B = {a,b,c,d}. How many injective (one‑to‑one) functions can be defined from A to B?",
    "options": {
      "A": "12",
      "B": "24",
      "C": "64",
      "D": "24 (4!)"
    },
    "correct_answer": "B",
    "explanation": "An injective function chooses distinct images for the three elements of A from the four elements of B: P(4,3) = 4·3·2 = 24.",
    "difficulty": "Medium"
  },
  {
    "question": "For the relation R on {a,b,c} given by R = {(a,a),(b,b),(c,c),(a,b)}, which properties are satisfied?",
    "options": {
      "A": "Reflexive only",
      "B": "Reflexive and symmetric",
      "C": "Reflexive and transitive",
      "D": "Symmetric only"
    },
    "correct_answer": "C",
    "explanation": "All required (x,x) pairs are present, so R is reflexive. No pair (b,a) exists, so it is not symmetric. The only possible chains satisfy transitivity, making R transitive.",
    "difficulty": "Medium"
  },
  {
    "question": "If a relation R on a set S is antisymmetric and transitive, which statement must always be true?",
    "options": {
      "A": "R is reflexive.",
      "B": "R is symmetric.",
      "C": "R is a partial order.",
      "D": "Whenever aRb and bRa hold, then a = b."
    },
    "correct_answer": "D",
    "explanation": "Antisymmetry guarantees that aRb and bRa can occur only when a and b are the same element; transitivity does not affect this condition.",
    "difficulty": "Medium"
  },
  {
    "question": "How many distinct equivalence relations exist on a set containing exactly two elements?",
    "options": {
      "A": "1",
      "B": "2",
      "C": "3",
      "D": "4"
    },
    "correct_answer": "B",
    "explanation": "Equivalence relations correspond to partitions of the set. For two elements the partitions are {{x},{y}} and {{x,y}}, giving two equivalence relations.",
    "difficulty": "Medium"
  }
]
